#define FILE_FD 3
#define SYNC_OFFSET 4096
#define SYNC_BYTES 8192
int ret_val;

/* Write dirty pages immediately (non-blocking wait) */
unsigned int F_WRITE = SYNC_FILE_RANGE_WRITE;

/* Wait for currently committed IO to complete */
unsigned int F_WAIT_B = SYNC_FILE_RANGE_WAIT_BEFORE;

/* Full sync: Wait, Write, Wait again */
unsigned int F_FULL = F_WAIT_B
                    | F_WRITE
                    | SYNC_FILE_RANGE_WAIT_AFTER;

/* Call structure: ARM architecture specific */
ret_val = arm_sync_file_range(
    FILE_FD,
    (off_t)SYNC_OFFSET,
    (off_t)SYNC_BYTES,
    F_FULL
);

/* Sync entire file (nbytes=0) */
ret_val = arm_sync_file_range(FILE_FD, 0, 0, F_WRITE);
